import os
import sqlite3
from pathlib import Path
from typing import Any, Callable, Dict, Optional

from fastapi import FastAPI, Request, Response, HTTPException, Depends, status
from fastapi.responses import JSONResponse
from starlette.middleware.sessions import SessionMiddleware
from pydantic import BaseModel, Field, validator

# Types
SessionObserver = Callable[[Dict[str, Any]], None]

# ---------- Database utilities (mirroring legacy_app/db.py) ----------

def connect_database(database_path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(database_path, detect_types=sqlite3.PARSE_DECLTYPES)
    conn.row_factory = sqlite3.Row
    return conn

def get_db(request: Request) -> sqlite3.Connection:
    if not hasattr(request.state, "db"):
        raise RuntimeError("Database not attached to request")
    return request.state.db

def close_db(request: Request) -> None:
    db: Optional[sqlite3.Connection] = getattr(request.state, "db", None)
    if db is not None:
        db.close()

def initialize_database(database_path: str) -> None:
    conn = connect_database(database_path)
    try:
        conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS tickets (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                owner_id TEXT NOT NULL,
                subject TEXT NOT NULL,
                description TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'open'
            );
            """
        )
        conn.commit()
    finally:
        conn.close()

# ---------- Pydantic models ----------
class SessionStartPayload(BaseModel):
    user_id: str = Field(..., min_length=1, max_length=64)

    @validator("user_id")
    def strip_user_id(cls, v: str) -> str:
        return v.strip()

class TicketCreatePayload(BaseModel):
    subject: str = Field(..., min_length=1)
    description: str = ""

    @validator("subject")
    def strip_subject(cls, v: str) -> str:
        return v.strip()

class TicketStatusUpdatePayload(BaseModel):
    status: str = Field(..., min_length=1)

# ---------- Helper for error responses ----------
def error_response(code: str, message: str, http_status: int) -> JSONResponse:
    return JSONResponse(content={"code": code, "message": message}, status_code=http_status)

# ---------- FastAPI app factory ----------
def create_app(test_config: Optional[Dict[str, Any]] = None) -> FastAPI:
    """Create a FastAPI app compatible with the legacy test harness.

    test_config may contain:
        - DATABASE: path to the SQLite file used by the harness.
        - SECRET_KEY: secret for signing session cookies.
        - SESSION_OBSERVER: a callable invoked with before/after session state.
    """
    app = FastAPI()

    # Default configuration
    config: Dict[str, Any] = {
        "SECRET_KEY": os.environ.get("LEGACYLIFT_SECRET_KEY", "local-development-only"),
        "DATABASE": str(Path("instance") / "legacylift.sqlite3"),
        "SESSION_OBSERVER": None,
    }

    if test_config:
        config.update(test_config)

    # Ensure database file directory exists and initialize schema if missing
    db_path = Path(config["DATABASE"])
    db_path.parent.mkdir(parents=True, exist_ok=True)
    if not db_path.exists():
        initialize_database(str(db_path))

    # Session middleware (uses signed cookie)

    # Dependency that attaches a DB connection to the request state
    async def db_dependency(request: Request):
        request.state.db = connect_database(config["DATABASE"])
        try:
            yield request.state.db
        finally:
            close_db(request)

    @app.middleware("http")
    async def observe_request_session(request: Request, call_next):
        before = {"user_id": request.session.get("user_id")}
        response = await call_next(request)
        observer = config.get("SESSION_OBSERVER")
        if observer and request.url.path.startswith(("/session", "/tickets")):
            observer({"before": before, "after": {"user_id": request.session.get("user_id")}})
        return response

    # Utility to invoke SESSION_OBSERVER with before/after snapshots
    def observe_session(request: Request, before: Dict[str, Any]):
        observer: Optional[SessionObserver] = config.get("SESSION_OBSERVER")
        if observer:
            after = dict(request.session) if hasattr(request, "session") else {}
            observer({"before": before, "after": after})

    # ---------- Routes ----------
    @app.post("/session")
    async def start_test_session(request: Request, payload: SessionStartPayload):
        before = dict(request.session) if hasattr(request, "session") else {}
        # Clear existing session and set new user_id
        request.session.clear()
        request.session["user_id"] = payload.user_id
        response = JSONResponse(content={"user_id": request.session["user_id"]})
        # Ensure Set-Cookie header is sent (FastAPI's SessionMiddleware handles it)
        return response

    @app.post("/tickets")
    async def create_ticket(
        request: Request,
        payload: TicketCreatePayload,
        db: sqlite3.Connection = Depends(db_dependency),
    ):
        before = dict(request.session) if hasattr(request, "session") else {}
        user_id = request.session.get("user_id")
        if user_id is None:
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail={"code": "authentication_required", "message": "start a session before creating tickets"},
            )
        cursor = db.execute(
            "INSERT INTO tickets (owner_id, subject, description) VALUES (?, ?, ?)",
            (user_id, payload.subject, payload.description),
        )
        db.commit()
        ticket_id = cursor.lastrowid
        return JSONResponse(content={"id": ticket_id, "owner_id": user_id, "subject": payload.subject, "description": payload.description, "status": "open"})

    @app.get("/tickets/{ticket_id}")
    async def get_ticket(
        request: Request,
        ticket_id: int,
        db: sqlite3.Connection = Depends(db_dependency),
    ):
        before = dict(request.session) if hasattr(request, "session") else {}
        row = db.execute("SELECT * FROM tickets WHERE id = ?", (ticket_id,)).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Ticket not found")
        return JSONResponse(content=dict(row))

    @app.patch("/tickets/{ticket_id}/status")
    async def update_ticket_status(
        request: Request,
        ticket_id: int,
        payload: TicketStatusUpdatePayload,
        db: sqlite3.Connection = Depends(db_dependency),
    ):
        before = dict(request.session) if hasattr(request, "session") else {}
        user_id = request.session.get("user_id")
        if user_id is None:
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail={"code": "authentication_required", "message": "start a session before updating tickets"},
            )
        # Verify ticket exists and belongs to the user (optional, mirrors legacy behavior)
        row = db.execute("SELECT owner_id FROM tickets WHERE id = ?", (ticket_id,)).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Ticket not found")
        db.execute(
            "UPDATE tickets SET status = ? WHERE id = ?",
            (payload.status, ticket_id),
        )
        db.commit()
        return JSONResponse(content={"id": ticket_id, "status": payload.status})

    app.add_middleware(SessionMiddleware, secret_key=config["SECRET_KEY"], session_cookie="session")

    return app
